{
  "taxonomy": [
    {
      "intent": "order_status",
      "definition": "Customer wants to know the current status or tracking details of an order",
      "merged_from": [],
      "examples_description": "Queries about where an order is, estimated delivery date, or tracking number"
    },
    {
      "intent": "return_refund",
      "definition": "Customer requests to return an item or inquires about a refund process",
      "merged_from": [],
      "examples_description": "Requests to start a return, questions about refund timing, or return label issues"
    },
    {
      "intent": "payment_issue",
      "definition": "Customer encounters problems with payment methods, charges, or billing",
      "merged_from": [],
      "examples_description": "Failed payments, unauthorized charges, requests to update payment info, or invoice disputes"
    },
    {
      "intent": "product_question",
      "definition": "Customer seeks information about a product's features, compatibility, or usage",
      "merged_from": [],
      "examples_description": "Questions about specifications, how to use a product, or whether an item meets a need"
    },
    {
      "intent": "shipping_delivery",
      "definition": "Customer reports problems with shipping, delivery, or package condition",
      "merged_from": [],
      "examples_description": "Late deliveries, missing packages, damaged items upon arrival, or address correction requests"
    },
    {
      "intent": "account_issue",
      "definition": "Customer needs help with account access, settings, or profile management",
      "merged_from": [],
      "examples_description": "Login problems, password reset, updating email/phone, or subscription management"
    },
    {
      "intent": "technical_support",
      "definition": "Customer experiences technical difficulties with Amazon services, apps, or devices",
      "merged_from": [],
      "examples_description": "Website errors, app crashes, Kindle/Alexa device troubleshooting, or streaming issues"
    },
    {
      "intent": "other_unclear",
      "definition": "Messages that do not fit any defined intent or are too vague to categorize",
      "merged_from": [],
      "examples_description": "Ambiguous feedback, general compliments/complaints, or off‑topic inquiries"
    }
  ]
}

